const SKEY='b2b_customer_profile_v19';const CKEY='b2b_cart_v19';
let PRODUCTS=[];
let cfg={deliveryFee:0,upiId:'',qrCode:'',discountEnabled:true,discountPercent:0,saleEnabled:false,quantityOffers:{},posters:[],offerEnabled:true,offerHeadline:'Special PVC Card Offer',offerSubtext:'Limited-time discount available',offerStart:'',offerEnd:'',offerPoster:'',whatsappNumber:'',themePreset:'vibrant',accentColor:'#7c3aed',brandName:'B2B PVC PRINTING SHOP',tagline:'Smart PVC Card Printing & Order',backgroundColor:'#f7f8ff',textColor:'#111827',buttonColor:'#7c3aed',headingSize:32,logo:''};
let pendingAction=null,captcha='',owner=false,submitting=false,appliedCoupon=null;
const $=id=>document.getElementById(id);const val=(id,d='')=>{const e=$(id);return e&&typeof e.value!=='undefined'?e.value:d};const checked=id=>!!($(id)?.checked);const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
async function imageData(id){const input=$(id);if(!input||!input.files||!input.files.length)return '';const file=input.files[0];return await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>{const img=new Image();img.onload=()=>{try{const max=640,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),cv=document.createElement('canvas');cv.width=w;cv.height=h;const ctx=cv.getContext('2d');if(!ctx)throw new Error('Browser image editor is unavailable.');ctx.drawImage(img,0,0,w,h);let q=.58,data=cv.toDataURL('image/jpeg',q);while(data.length>90000&&q>.25){q-=.06;data=cv.toDataURL('image/jpeg',q)}resolve(data)}catch(e){reject(e)}};img.onerror=()=>reject(new Error('Image could not be read.'));img.src=String(fr.result||'')};fr.onerror=()=>reject(new Error('Image could not be read.'));fr.readAsDataURL(file)})}
async function imageDataMulti(id){const input=$(id);if(!input?.files?.length)return [];const files=Array.from(input.files).slice(0,3);const out=[];for(const file of files){out.push(await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>{const img=new Image();img.onload=()=>{const max=1200,s=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*s)),h=Math.max(1,Math.round(img.height*s)),cv=document.createElement('canvas');cv.width=w;cv.height=h;cv.getContext('2d').drawImage(img,0,0,w,h);resolve(cv.toDataURL('image/jpeg',.72))};img.onerror=()=>reject(new Error('Image could not be read.'));img.src=fr.result};fr.onerror=()=>reject(new Error('Image could not be read.'));fr.readAsDataURL(file)}));}return out}
function applyBranding(){const root=document.documentElement;const a=/^#[0-9a-fA-F]{6}$/.test(cfg.accentColor||'')?cfg.accentColor:'#7c3aed';const bg=/^#[0-9a-fA-F]{6}$/.test(cfg.backgroundColor||'')?cfg.backgroundColor:'#f7f8ff';const tc=/^#[0-9a-fA-F]{6}$/.test(cfg.textColor||'')?cfg.textColor:'#111827';const bc=/^#[0-9a-fA-F]{6}$/.test(cfg.buttonColor||'')?cfg.buttonColor:a;root.style.setProperty('--p',bc);root.style.setProperty('--p2',bc);root.style.setProperty('--accent',a);root.style.setProperty('--bg',bg);root.style.setProperty('--ink',tc);root.style.setProperty('--button',bc);root.style.setProperty('--heroSize',(Number(cfg.headingSize)||32)+'px');document.title=cfg.brandName||'B2B PVC PRINTING SHOP';const logo=$('logo');if(logo)logo.src=cfg.logo||'';const bn=document.querySelector('.brand b');if(bn)bn.textContent=cfg.brandName||'B2B PVC PRINTING SHOP';const bs=document.querySelector('.brand small');if(bs)bs.textContent=cfg.tagline||'Smart PVC Card Printing & Order';const ht=$('heroTitle');if(ht){ht.textContent=cfg.brandName||'Premium PVC Smart Card Printing';ht.style.fontSize=(Number(cfg.headingSize)||32)+'px'}const hs=$('heroSub');if(hs)hs.textContent=cfg.tagline||'Choose your product, add to cart, verify once, pay securely and receive your bill instantly.';document.body.style.color=tc;document.body.style.background='linear-gradient(180deg,'+bg+' 0,#fff 280px)';document.querySelectorAll('.btn.primary').forEach(x=>x.style.background=bc)}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}function openM(id){$(id).classList.add('show')}function closeM(id){$(id).classList.remove('show')}
function getProfile(){try{return JSON.parse(sessionStorage.getItem(SKEY)||'null')}catch{return null}}function setProfile(p){sessionStorage.setItem(SKEY,JSON.stringify(p));updateProfileBtn()}function getCart(){try{return JSON.parse(localStorage.getItem(CKEY)||'[]')}catch{return []}}function setCart(c){localStorage.setItem(CKEY,JSON.stringify(c));updateCartCount()}function updateCartCount(){$('cartCount').textContent=getCart().reduce((n,x)=>n+Number(x.qty||1),0)}
function newCaptcha(){captcha=String(Math.floor(1000+Math.random()*9000));$('captchaCode').textContent=captcha}newCaptcha();
function updateProfileBtn(){const p=getProfile();$('profileBtn').textContent=p?`👤 ${p.name}`:'👤 Profile'}updateProfileBtn();
async function ensureVerified(action){const p=getProfile();if(p&&!sessionStorage.getItem('customer_logged_out')){try{const r=await fetch('/api/customer/me',{cache:'no-store',credentials:'same-origin'});if(r.ok){action();return}}catch{}sessionStorage.removeItem(SKEY)}pendingAction=action;openM('verifyModal');newCaptcha();$('vName').value=p?.name||'';$('vPhone').value=p?.phone||'';$('vCaptcha').value='';$('vName').focus()}
async function verifyGuest(){if(window.__verifying)return;const n=$('vName').value.trim(),p=$('vPhone').value.replace(/\D/g,'').slice(-10),c=$('vCaptcha').value.trim();if(n.length<2)return toast('Please enter your name.');if(p.length!==10)return toast('Please enter a valid 10 digit mobile number.');if(!/^\d{4}$/.test(c)||c!==captcha)return toast('Enter the 4 digit CAPTCHA correctly.');const a=pendingAction;if(!a)return closeM('verifyModal');window.__verifying=true;const btn=document.querySelector('#verifyModal .btn.primary');if(btn){btn.disabled=true;btn.textContent='⏳ Verifying...'}try{const r=await fetch('/api/customer/login',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({name:n,phone:p})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Customer verification failed.');sessionStorage.removeItem('customer_logged_out');setProfile({name:n,phone:p,verifiedAt:Date.now()});pendingAction=null;closeM('verifyModal');a();}catch(e){toast('❌ '+e.message)}finally{window.__verifying=false;if(btn){btn.disabled=false;btn.textContent='✅ Verify & Continue'}}}
function getProductQtyMap(){try{return JSON.parse(localStorage.getItem('b2b_product_qty_v18')||'{}')}catch{return {}}} function qtyFor(id){const c=getCart().find(x=>x.id===id);if(c)return Math.max(1,Number(c.qty)||1);const m=getProductQtyMap();return Math.max(1,Math.min(999,Number(m[id])||1))}function setQty(id,q){q=Math.max(1,Math.min(999,Number(q)||1));const c=getCart(),x=c.find(i=>i.id===id);if(x)x.qty=q;setCart(c);renderCart();}
function offersFor(pr){const q=Array.isArray(pr.quantityOffers)&&pr.quantityOffers.length?pr.quantityOffers:cfg.quantityOffers?.[pr.id];if(Array.isArray(q)&&q.length)return q.sort((a,b)=>Number(a.min)-Number(b.min));return [{min:1,price:Number(pr.price)||0},{min:5,price:Number(pr.price)||0},{min:10,price:Number(pr.price)||0},{min:25,price:Number(pr.price)||0},{min:50,price:Number(pr.price)||0}]}
function unitPrice(pr,qty){const t=offersFor(pr).filter(x=>qty>=Number(x.min)).sort((a,b)=>Number(b.min)-Number(a.min))[0];let v=Number(t?.price??pr.price??0);if(cfg.discountEnabled&&Number(cfg.discountPercent)>0)v=Math.max(0,v*(1-Number(cfg.discountPercent)/100));return Math.round(v*100)/100}
function totals(){let subtotal=0,mrp=0;for(const x of getCart()){const p=PRODUCTS.find(a=>a.id===x.id);if(!p)continue;const q=Number(x.qty)||1;subtotal+=unitPrice(p,q)*q;mrp+=(Number(p.normalPrice)||Number(p.price)||0)*q}const discount=Math.max(0,mrp-subtotal),delivery=getCart().length?Number(cfg.deliveryFee)||0:0;return {subtotal,mrp,discount,delivery,total:subtotal+delivery}}
function activeOffer(){if(cfg.offerEnabled===false)return null;const now=Date.now(),st=cfg.offerStart?Date.parse(cfg.offerStart):0,en=cfg.offerEnd?Date.parse(cfg.offerEnd):0;if(st&&now<st)return null;if(en&&now>en)return null;return cfg.offerHeadline||cfg.offerSubtext||cfg.offerPoster?cfg:null}
function renderOffer(){const o=activeOffer(),b=$('offerBanner');if(!o){if(b)b.innerHTML='';return}const end=o.offerEnd?Date.parse(o.offerEnd):0;const timer=end&&end>Date.now()?`<span class="offerTimer">Ends ${new Date(end).toLocaleString()}</span>`:'';const cards=Array.isArray(o.posters)&&o.posters.length?o.posters.map(x=>`<div class="customPoster" style="background:${esc(x.bgColor||'#7c3aed')};color:${esc(x.textColor||'#fff')};text-align:${esc(x.align||'center')};font-size:${Number(x.fontSize)||24}px;font-style:${esc(x.fontStyle||'bold')}">${x.image?`<img src="${esc(x.image)}" alt="Poster">`:''}<div><b>${esc(x.title||'Offer')}</b><div>${esc(x.text||'')}</div></div></div>`).join(''):`<div class="offerCard">${o.offerPoster?`<img src="${o.offerPoster}" style="width:100px;height:70px;object-fit:cover;border-radius:12px;background:#fff">`:''}<div style="flex:1"><h2>🎉 ${esc(o.offerHeadline||'Special Offer')}</h2><p>${esc(o.offerSubtext||'Limited-time offer available now')}</p></div>${timer}</div>`;b.innerHTML=cards;const n=$('offerNotice'),nt=$('offerNoticeText');if(n&&nt&&!sessionStorage.getItem('offer_notice_seen')){nt.textContent=o.offerSubtext||o.offerHeadline||'Special offer is active now.';n.classList.add('show');sessionStorage.setItem('offer_notice_seen','1')}}
function hideOfferNotice(){$('offerNotice')?.classList.remove('show')}
function applyTheme(){applyBranding();document.body.dataset.theme=cfg.themePreset||'vibrant'}
async function restoreCustomerSession(){if(sessionStorage.getItem('customer_logged_out'))return;try{const r=await fetch('/api/customer/me',{cache:'no-store',credentials:'same-origin'});if(r.ok){const d=await r.json();setProfile({name:d.name,phone:d.phone,verifiedAt:Date.now()})}}catch{}}
function renderProducts(){const q=$('search').value.trim().toLowerCase();$('grid').innerHTML='';PRODUCTS.filter(p=>!q||p.title.toLowerCase().includes(q)||(p.tag||'').toLowerCase().includes(q)).forEach(p=>{const qty=qtyFor(p.id),u=unitPrice(p,qty),item=document.createElement('article');item.className='product';const gallery=(p.images||[]).slice(0,3);item.innerHTML=`<div class="pic"><img id="mainimg_${p.id}" loading="lazy" decoding="async" src="${gallery[0]||''}" alt="${esc(p.title)}"></div>${gallery.length>1?`<div class="thumbs">${gallery.map((g,i)=>`<img loading="lazy" src="${g}" alt="${esc(p.title)} ${i+1}" onclick="document.getElementById('mainimg_${p.id}').src='${g}'">`).join('')}</div>`:''}<div class="pbody"><span class="tag">${esc(p.tag||'PVC Card')}</span>${(cfg.saleEnabled||p.offerBadge)?'<span class="sale">'+esc(p.offerBadge||'SALE')+'</span>':''}<h3>${esc(p.title)}</h3><div class="desc">${esc(p.desc||'Premium PVC printing')}</div><div class="price"><span class="old">₹${Number(p.normalPrice||0)}</span><span class="new">₹${u}</span></div><div class="qtyrow"><b>Qty</b><button onclick="changeProductQty('${p.id}',-1)">−</button><input id="pq_${p.id}" value="${qty}" inputmode="numeric" onchange="changeProductQty('${p.id}',0,this.value)"><button onclick="changeProductQty('${p.id}',1)">+</button></div><div class="actions"><button class="btn primary" onclick="addToCart('${p.id}')">🛒 Add to Cart</button><button class="btn green" onclick="buyNow('${p.id}')">⚡ Buy Now</button></div></div>`;$('grid').appendChild(item)})}
function changeProductQty(id,d,val){let q=val!==undefined?Number(val):qtyFor(id)+d;q=Math.max(1,Math.min(999,q));const c=getCart();let x=c.find(i=>i.id===id);if(x){x.qty=q;setCart(c)}else{const m=getProductQtyMap();m[id]=q;localStorage.setItem('b2b_product_qty_v18',JSON.stringify(m));const inp=$('pq_'+id);if(inp)inp.value=q}renderProducts()}
function addToCart(id){ensureVerified(()=>{const c=getCart(),q=Number($('pq_'+id)?.value||1);const x=c.find(i=>i.id===id);if(x)x.qty+=q;else c.push({id,qty:q});setCart(c);renderProducts();toast('Product added to Cart');openCart()})}
function buyNow(id){ensureVerified(()=>{const q=Number($('pq_'+id)?.value||1);setCart([{id,qty:q}]);openCart()})}
function openCart(){renderCart();openM('cartModal')}
function renderCart(){const c=getCart();if(!c.length){$('cartItems').innerHTML='<div style="text-align:center;padding:35px;color:#64748b">🛒 Cart is empty.</div>';$('cartSummary').innerHTML='';return}let h='';for(const x of c){const p=PRODUCTS.find(a=>a.id===x.id);if(!p)continue;const q=Number(x.qty)||1,u=unitPrice(p,q);h+=`<div class="cartitem"><img src="${p.images?.[0]||''}"><div><b>${esc(p.title)}</b><div class="mini">₹${u} × ${q} = ₹${(u*q).toFixed(2)}</div><div style="margin-top:7px"><button class="btn light" onclick="setQty('${p.id}',${q-1})">−</button> <b style="padding:0 10px">${q}</b> <button class="btn light" onclick="setQty('${p.id}',${q+1})">+</button></div></div><button class="btn red" onclick="removeCart('${p.id}')">Remove</button></div>`}$('cartItems').innerHTML=h;const t=totals();$('cartSummary').innerHTML=`<div class="summary"><div class="line"><span>Subtotal</span><b>₹${t.subtotal.toFixed(2)}</b></div><div class="line"><span>Discount</span><b style="color:#047857">− ₹${t.discount.toFixed(2)}</b></div><div class="line"><span>Delivery</span><b>₹${t.delivery.toFixed(2)}</b></div><div class="line total"><span>Grand Total</span><b>₹${t.total.toFixed(2)}</b></div></div>`}
function removeCart(id){setCart(getCart().filter(x=>x.id!==id));renderCart();renderProducts()}
async function loadProducts(){try{const r=await fetch('/api/products',{cache:'no-store'});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load products.');PRODUCTS=Array.isArray(d.products)?d.products:[];renderProducts()}catch(e){$('grid').innerHTML='<div style="grid-column:1/-1;text-align:center;padding:35px;color:#b91c1c;font-weight:800">❌ '+esc(e.message)+'</div>'}}
async function loadCfg(){try{const r=await fetch('/api/site-config',{cache:'no-store'});if(r.ok){const d=await r.json();cfg={...cfg,...(d.config||{})};}}catch{}applyBranding();renderProducts();renderOffer()}
function goCheckout(){if(!getCart().length)return toast('Cart is empty.');if(!getProfile()){closeM('cartModal');return ensureVerified(goCheckout)}renderCheckout();closeM('cartModal');openM('checkoutModal')}
function renderCheckout(){const t=totals(),couponDisc=Number(appliedCoupon?.discount||0),displayTotal=Math.max(0,t.total-couponDisc);let rows=getCart().map(x=>{const p=PRODUCTS.find(a=>a.id===x.id);const q=Number(x.qty)||1;return `<div class="line"><span>${esc(p.title)} × ${q}<br><small>₹${unitPrice(p,q).toFixed(2)} each</small></span><b>₹${(unitPrice(p,q)*q).toFixed(2)}</b></div>`}).join('');$('checkoutSummary').innerHTML=`<div class="summary">${rows}<div class="line"><span>Subtotal</span><b>₹${t.subtotal.toFixed(2)}</b></div><div class="line"><span>Discount</span><b style="color:#047857">− ₹${t.discount.toFixed(2)}</b></div>${couponDisc?`<div class="line"><span>Coupon ${esc(appliedCoupon.code)}</span><b style="color:#047857">− ₹${couponDisc.toFixed(2)}</b></div>`:''}<div class="line"><span>Delivery</span><b>₹${t.delivery.toFixed(2)}</b></div><div class="line total"><span>Grand Total</span><b>₹${displayTotal.toFixed(2)}</b></div></div>`;const ci=$('checkoutCoupon');if(ci)ci.value=appliedCoupon?.code||'';const cr=$('couponResult');if(cr)cr.innerHTML=appliedCoupon?`<span style="color:#047857;font-weight:800">Coupon ${esc(appliedCoupon.code)} applied: − ₹${couponDisc.toFixed(2)}</span>`:'';const p=getProfile()||{};$('checkoutName').textContent=p.name||'—';$('checkoutPhone').textContent=p.phone||'—';$('cAddress').value=p.address||'';$('cPin').value=p.pin||'';$('cLandmark').value=p.landmark||'';$('cEmail').value=p.email||'';$('cNote').value=p.note||'';const qr=cfg.qrCode;$('payQR').src=qr||'';$('payQR').classList.toggle('hidden',!qr);$('noQR').classList.toggle('hidden',!!qr);$('upiText').textContent=cfg.upiId?`UPI ID: ${cfg.upiId}`:'UPI ID not configured';const data=cfg.upiId?upiPaymentLinks(cfg.upiId,displayTotal):{};[['upiPayBtn',data.upi],['phonePeBtn',data.phonepe],['gpayBtn',data.gpay],['paytmBtn',data.paytm]].forEach(([id,url])=>{const el=$(id);if(el){el.href=url||'#';el.style.display=url?'inline-block':'none'}});}
async function fileData(){const f=$('cShot').files?.[0];if(!f)return '';if(f.size>8*1024*1024)throw new Error('Payment screenshot is too large.');return await new Promise((res,rej)=>{const img=new Image();const r=new FileReader();r.onload=()=>{img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),cv=document.createElement('canvas');cv.width=w;cv.height=h;cv.getContext('2d').drawImage(img,0,0,w,h);let q=0.78,data=cv.toDataURL('image/jpeg',q);while(data.length>520000&&q>0.45){q-=0.07;data=cv.toDataURL('image/jpeg',q)}res(data)};img.onerror=rej;img.src=String(r.result||'')};r.onerror=rej;r.readAsDataURL(f)})}
async function confirmOrder(){if(submitting)return;const p=getProfile();if(!p)return goCheckout();const address=$('cAddress').value.trim(),pin=$('cPin').value.replace(/\D/g,''),landmark=$('cLandmark').value.trim(),email=$('cEmail').value.trim(),note=$('cNote').value.trim(),txn=$('cTxn').value.trim();if(!address)return toast('Full address is required.');if(!/^\d{6}$/.test(pin))return toast('Enter a valid 6 digit PIN.');if(email&&!/^\S+@\S+\.\S+$/.test(email))return toast('Enter a valid email or leave it blank.');if(!txn&&!$('cShot').files?.length)return toast('Enter UTR or upload payment screenshot.');submitting=true;$('confirmBtn').disabled=true;$('confirmBtn').textContent='⏳ Saving Order...';let waWin=null;try{if(cfg.whatsappNumber)waWin=window.open('about:blank','_blank');const shot=await fileData(),t=totals(),items=getCart().map(x=>{const pr=PRODUCTS.find(a=>a.id===x.id);const q=Number(x.qty)||1;return {id:pr.id,title:pr.title,quantity:q,unitPrice:unitPrice(pr,q),mrp:Number(pr.normalPrice)||0,total:unitPrice(pr,q)*q}});const r=await fetch('/api/guest-order',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:p.name,phone:p.phone,address,pin,landmark,email,note,items,subtotal:t.subtotal,mrpTotal:t.mrp,delivery:t.delivery,total:t.total,paymentTxn:txn,couponCode:appliedCoupon?.code||'',paymentScreenshot:shot})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Order could not be saved.');setProfile({...p,address,pin,landmark,email,note});setCart([]);closeM('checkoutModal');appliedCoupon=null;showReceipt(d.receipt||{orderNo:d.orderNo,paymentRef:d.paymentRef||'',name:p.name,phone:p.phone,address,pin,landmark,email,note,items,subtotal:t.subtotal,discount:t.discount,delivery:t.delivery,total:t.total,paymentTxn:txn,hasPaymentScreenshot:!!shot,status:'Payment Submitted',createdAt:new Date().toISOString()});if(cfg.whatsappNumber){const msg=`New Purchase Order\nOrder ID: ${d.orderNo}\nCustomer: ${p.name}\nMobile: ${p.phone}\nProduct: ${items.map(i=>i.title+' x '+i.quantity).join(', ')}\nTotal: ₹${Number(t.total).toFixed(2)}\nAddress: ${address}, PIN ${pin}\nPayment: ${txn||'Screenshot submitted'}`;const url='https://wa.me/91'+cfg.whatsappNumber+'?text='+encodeURIComponent(msg);if(waWin&&!waWin.closed)waWin.location=url;else window.open(url,'_blank')}toast(d.screenshotSaved===false?'Order saved. Payment screenshot could not be stored, but purchase is saved.':'Order confirmed successfully');}catch(e){if(waWin&&!waWin.closed)waWin.close();toast(e.message||'Order failed')}finally{submitting=false;$('confirmBtn').disabled=false;$('confirmBtn').textContent='💳 Confirm Payment & Place Order'}}
function showReceipt(r){let rows=(r.items||[]).map(i=>`<div class="line"><span>${esc(i.title)} × ${i.quantity}<br><small>₹${Number(i.unitPrice).toFixed(2)} each</small></span><b>₹${Number(i.total).toFixed(2)}</b></div>`).join('');$('receiptArea').innerHTML=`<div class="receipt"><div class="receiptHead"><div><h2>B2B PVC PRINTING SHOP</h2><div class="mini">Purchase Bill / Payment Receipt</div></div><div style="text-align:right"><b>Order ID</b><br>${esc(r.orderNo)}<br><small>${new Date(r.createdAt||Date.now()).toLocaleString()}</small></div></div><div class="summary"><div class="line"><span>Customer</span><b>${esc(r.name)}</b></div><div class="line"><span>Mobile</span><b>${esc(r.phone)}</b></div><div class="line"><span>Address</span><b style="text-align:right;max-width:65%">${esc(r.address)} - ${esc(r.pin)}</b></div></div><h3>Purchase Details</h3><div class="summary">${rows}<div class="line"><span>Subtotal</span><b>₹${Number(r.subtotal).toFixed(2)}</b></div><div class="line"><span>Discount</span><b style="color:#047857">− ₹${Number(r.discount||0).toFixed(2)}</b></div><div class="line"><span>Delivery</span><b>₹${Number(r.delivery).toFixed(2)}</b></div><div class="line total"><span>Grand Total</span><b>₹${Number(r.total).toFixed(2)}</b></div></div><div style="margin-top:15px;padding:13px;border-radius:12px;background:#ecfdf5"><b>Payment Reference:</b> ${esc(r.paymentRef||'Auto generated')}<br><b>Payment:</b> ${r.paymentTxn?'UTR '+esc(r.paymentTxn):'Screenshot submitted'}${r.couponCode?`<br><b>Coupon:</b> ${esc(r.couponCode)} − ₹${Number(r.couponDiscount||0).toFixed(2)}`:''}<br><b>Status:</b> ${esc(r.status||'Payment Submitted')}</div><div class="footnote">Thank you for your order.</div></div>`;openM('receiptModal')}
async function openProfile(){const p=getProfile();$('profileContent').innerHTML=p?`<div class=\"verifyHead\"><b>Verified Customer</b><div style=\"margin-top:5px;color:#334155\">Name and mobile are linked to your customer order history.</div></div><div class=\"field\"><label>Name</label><input value=\"${esc(p.name)}\" disabled></div><div class=\"field\"><label>Mobile</label><input value=\"${esc(p.phone)}\" disabled></div><div id=\"customerHistory\" style=\"margin-top:15px\">Loading order history...</div><div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:15px\"><button class=\"btn primary\" onclick=\"openSupport('Feedback')\">💬 Feedback</button><button class=\"btn light\" onclick=\"openSupport('Service')\">🛠 Service Request</button><button class=\"btn red\" onclick=\"openSupport('Complaint')\">⚠️ Complaint</button><button class=\"btn red\" onclick=\"guestLogout()\">🚪 Logout</button></div>`:`<div style=\"text-align:center;padding:20px\">No customer session yet.<br><button class=\"btn primary\" style=\"margin-top:12px\" onclick=\"closeM('profileModal');ensureVerified(()=>openProfile())\">Verify Name + Mobile</button></div>`;openM('profileModal');if(p)loadCustomerHistory()}
async function loadCustomerHistory(){const box=$('customerHistory');if(!box)return;try{const r=await fetch('/api/customer/orders',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load orders.');const orders=d.orders||[];if(!orders.length){box.innerHTML='<div class=\"mini\">No previous orders found.</div>';return}let total=0;const rows=orders.map(o=>{total+=Number(o.total)||0;let items=[];try{items=JSON.parse(o.items_json||'[]')}catch{}return `<div class=\"historyCard\"><div><b>${esc(o.order_no)}</b><span class=\"badge\">${esc(o.status)}</span></div><div class=\"mini\">${new Date(o.created_at).toLocaleString()} • ${items.map(i=>esc(i.title)+' × '+Number(i.quantity||0)).join(', ')}</div><div style=\"display:flex;justify-content:space-between;align-items:center;margin-top:8px\"><b>₹${Number(o.total).toFixed(2)}</b><button class=\"btn light\" onclick=\"viewCustomerBill('${encodeURIComponent(o.order_no)}')\">🧾 View / Download Bill</button></div></div>`}).join('');box.innerHTML=`<h3 style=\"margin:0 0 10px\">📋 Previous Orders (${orders.length})</h3>${rows}<div class=\"line total\" style=\"margin-top:10px\"><span>Total Purchase Value</span><b>₹${total.toFixed(2)}</b></div>`}catch(e){box.innerHTML='<div style=\"color:#b91c1c\">'+esc(e.message)+'</div>'}}
async function viewCustomerBill(orderNo){try{const r=await fetch('/api/receipt/'+orderNo,{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Bill not found.');closeM('profileModal');showReceipt(d.receipt)}catch(e){toast(e.message)}}
async function guestLogout(){try{await fetch('/api/customer/logout',{method:'POST',credentials:'same-origin',cache:'no-store',keepalive:true})}catch{}sessionStorage.setItem('customer_logged_out','1');sessionStorage.removeItem(SKEY);localStorage.removeItem(CKEY);updateProfileBtn();updateCartCount();$('profileContent').innerHTML='';closeM('profileModal');renderProducts();toast('Customer logged out. Name, mobile and cart session cleared.')}
function openSupport(type='Contact'){const p=getProfile()||{};$('supportType').value=type;$('supportName').value=p.name||'';$('supportPhone').value=p.phone||'';$('supportEmail').value=p.email||'';$('supportSubject').value='';$('supportOrder').value='';$('supportMessage').value='';const c=cfg||{};const box=$('contactQuick');if(box)box.innerHTML=`<b>📞 Call:</b> ${esc(c.supportPhone||c.whatsappNumber||'Not set')} &nbsp; <b>✉️ Email:</b> ${esc(c.supportEmail||'Not set')} &nbsp; <b>💬 WhatsApp:</b> ${esc(c.whatsappNumber||'Not set')}`;openM('supportModal')}
async function sendSupport(){const p={name:$('supportName').value.trim(),phone:$('supportPhone').value.replace(/\D/g,'').slice(-10),email:$('supportEmail').value.trim(),type:$('supportType').value,subject:$('supportSubject').value.trim(),orderNo:$('supportOrder').value.trim(),message:$('supportMessage').value.trim()};if(p.name.length<2||p.phone.length!==10)return toast('Name and valid mobile are required.');if(p.message.length<3)return toast('Please enter your message.');try{const r=await fetch('/api/support',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify(p)}),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not send.');closeM('supportModal');toast('Your request has been submitted.')}catch(e){toast(e.message)}}
function openBusinessInfo(){const c=cfg||{};openSupport('Contact');setTimeout(()=>{const s=$('supportMessage');if(s&&!s.value)s.value='Please help me with my order / service.'},30)}
async function ownerLogin(){const pass=$('oPass').value;if(!pass)return $('ownerLoginErr').textContent='Enter Owner Password.';$('ownerLoginBtn').disabled=true;$('ownerLoginBtn').textContent='⏳ Checking...';$('ownerLoginErr').textContent='';try{const r=await fetch('/api/admin/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:pass})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Owner login failed.');owner=true;closeM('ownerLoginModal');openM('ownerModal');ownerHome();}catch(e){$('ownerLoginErr').textContent='❌ '+e.message}finally{$('ownerLoginBtn').disabled=false;$('ownerLoginBtn').textContent='🔓 Login to Owner Portal'}}
function openOwnerLogin(){if(owner){openM('ownerModal');ownerOrders();return}$('oPass').value='';$('ownerLoginErr').textContent='';openM('ownerLoginModal');setTimeout(()=>$('oPass').focus(),50)}
function openTrack(){openM('trackModal');$('trackOrder').focus();$('trackResult').innerHTML=''}
async function trackOrder(){const no=$('trackOrder').value.trim().toUpperCase(),last4=$('trackLast4').value.replace(/\D/g,'');if(!/^B2B-[A-Z0-9]{6}$/.test(no))return toast('Enter a valid short Order ID like B2B-7K4P2Q');if(!/^\d{4}$/.test(last4))return toast('Enter the last 4 digits of the mobile number used for the order.');$('trackResult').innerHTML='<div class="mini">⏳ Checking...</div>';try{const r=await fetch('/api/track/'+encodeURIComponent(no)+'?v='+last4,{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Order not found.');const o=d.order;const items=(o.items||[]).map(i=>esc(i.title)+' × '+Number(i.quantity||0)).join('<br>');$('trackResult').innerHTML=`<div class="summary"><div class="line"><span>Order ID</span><b>${esc(o.orderNo)}</b></div><div class="line"><span>Status</span><b class="badge">${esc(o.status)}</b></div><div class="line"><span>Customer</span><b>${esc(o.customerName)}</b></div><div class="line"><span>Mobile</span><b>******${esc(o.phone)}</b></div><div class="line"><span>Items</span><b style="text-align:right">${items}</b></div><div class="line total"><span>Total</span><b>₹${Number(o.total||0).toFixed(2)}</b></div><div class="line"><span>Delivery</span><b>${esc(o.deliveryPartner||'Not updated')} ${o.deliveryId?('• '+esc(o.deliveryId)):''}</b></div><div class="line"><span>Placed</span><b>${new Date(o.createdAt).toLocaleString()}</b></div></div>`}catch(e){$('trackResult').innerHTML='<div style="color:#b91c1c;font-weight:800">❌ '+esc(e.message)+'</div>'}}

function ownerHome(){if(!owner)return openOwnerLogin();$('ownerBody').innerHTML=`<div class="ownerDash"><div class="dashHero"><div><div class="eyebrow">OWNER CONTROL CENTER</div><h3 style="margin:5px 0">⚡ Ready to manage your shop</h3><p class="mini">Choose a section below. Data loads only when you open it, so the portal stays fast.</p></div></div><div class="dashGrid"><button class="dashCard" onclick="ownerOrders()">📋<b>Purchases</b><span>Orders & delivery tracking</span></button><button class="dashCard" onclick="ownerProducts()">🛍️<b>Products</b><span>Images, prices & offers</span></button><button class="dashCard" onclick="ownerSettings()">🎨<b>Website Design</b><span>Branding & colours</span></button><button class="dashCard" onclick="ownerSettingsPart('payment')">💳<b>Payment</b><span>UPI, QR & delivery</span></button><button class="dashCard" onclick="ownerSettingsPart('offer')">🎉<b>Offers</b><span>Poster & notification</span></button><button class="dashCard" onclick="ownerSupport()">💬<b>Customers</b><span>Feedback & complaints</span></button></div></div>`}

async function ownerOrders(){if(!owner)return openOwnerLogin();$('ownerBody').innerHTML='<div style="padding:25px;text-align:center">⏳ Loading purchases...</div>';try{const r=await fetch('/api/admin/orders',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to load orders.');const rows=(d.orders||[]).map(o=>{let items=[];try{items=JSON.parse(o.items_json||'[]')}catch{}const products=items.map(i=>`${esc(i.title||i.id)} × ${Number(i.quantity||0)}`).join('<br>');return `<tr><td><b>${esc(o.order_no)}</b></td><td>${esc(o.customer_name)}<br>${esc(o.phone)}</td><td>${esc(o.address)}<br>${esc(o.pin)}</td><td>${products}</td><td>₹${Number(o.total).toFixed(2)}<br>Delivery ₹${Number(o.delivery).toFixed(2)}</td><td>${esc(o.payment_txn||'Screenshot')}</td><td><select id="st_${esc(o.order_no)}"><option ${o.status==='Payment Submitted'?'selected':''}>Payment Submitted</option><option ${o.status==='Processing'?'selected':''}>Processing</option><option ${o.status==='Completed'?'selected':''}>Completed</option><option ${o.status==='Cancelled'?'selected':''}>Cancelled</option></select><input id="did_${esc(o.order_no)}" value="${esc(o.delivery_id||'')}" placeholder="Delivery / Tracking ID" style="margin-top:6px;width:150px;padding:7px;border:1px solid #cbd5e1;border-radius:8px"><input id="dpt_${esc(o.order_no)}" value="${esc(o.delivery_partner||'')}" placeholder="Courier" style="margin-top:6px;width:150px;padding:7px;border:1px solid #cbd5e1;border-radius:8px"><button class="btn green" style="margin-top:6px;padding:7px 10px" onclick="saveDelivery('${esc(o.order_no)}')">Save</button> <button class="btn red" style="margin-top:6px;padding:7px 10px" onclick="deleteOrder('${esc(o.order_no)}')">Delete</button><br><small>${new Date(o.created_at).toLocaleString()}</small></td></tr>`}).join('');$('ownerBody').innerHTML=`<h3>📋 All Purchases & Delivery Tracking (${d.orders?.length||0})</h3><div class="mini">Set courier/tracking ID and save it. Customers will see it in Track Order.</div><div class="tablewrap"><table class="table"><thead><tr><th>Order ID</th><th>Customer</th><th>Address / PIN</th><th>Product / Qty</th><th>Amount</th><th>Payment</th><th>Status / Delivery</th></tr></thead><tbody>${rows||'<tr><td colspan="7">No purchases yet.</td></tr>'}</tbody></table></div>`}catch(e){$('ownerBody').innerHTML='<div style="color:#b91c1c;font-weight:800">❌ '+esc(e.message)+'</div>'}}
async function deleteOrder(no){if(!confirm('Delete this purchase order permanently?'))return;try{const r=await fetch('/api/admin/orders/'+encodeURIComponent(no),{method:'DELETE'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Order delete failed.');toast('Purchase order deleted.');ownerOrders()}catch(e){toast('❌ '+e.message)}}
async function saveDelivery(no){try{const r=await fetch('/api/admin/orders/'+encodeURIComponent(no),{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status:document.getElementById('st_'+no).value,deliveryId:document.getElementById('did_'+no).value,deliveryPartner:document.getElementById('dpt_'+no).value})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Delivery save failed.');toast('Delivery tracking saved.');ownerOrders()}catch(e){toast('❌ '+e.message)}}
async function ownerSettings(){if(!owner)return openOwnerLogin();try{if(!cfg||!cfg.brandName){const r=await fetch('/api/site-config',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load settings.');cfg={...cfg,...(d.config||{})}}ownerSettingsPart('branding')}catch(e){$('ownerBody').innerHTML='<div style="color:#b91c1c;font-weight:800">❌ '+esc(e.message)+'</div>'}}
function ownerSettingsNav(active){return `<div class="ownerTabs"><button class="btn ${active==='branding'?'primary':'light'}" onclick="ownerSettingsPart('branding')">🎨 Branding</button><button class="btn ${active==='quantity'?'primary':'light'}" onclick="ownerSettingsPart('quantity')">📊 Quantity Offers</button><button class="btn ${active==='payment'?'primary':'light'}" onclick="ownerSettingsPart('payment')">💳 Payment & Delivery</button><button class="btn ${active==='offer'?'primary':'light'}" onclick="ownerSettingsPart('offer')">🎉 Offers</button><button class="btn ${active==='tracking'?'primary':'light'}" onclick="ownerOrders()">📦 Orders & Tracking</button></div>`}
async function ownerSettingsPart(part){if(!owner)return openOwnerLogin();
if(part==='branding'){$('ownerBody').innerHTML=ownerSettingsNav(part)+`<h3>🎨 Company / Website Design</h3><div class="checkoutGrid"><div class="field"><label>Company Name</label><input id="setBrandName" value="${esc(cfg.brandName||'B2B PVC PRINTING SHOP')}"></div><div class="field"><label>Tagline</label><input id="setTagline" value="${esc(cfg.tagline||'Smart PVC Card Printing & Order')}"></div><div class="field"><label>Theme</label><select id="setTheme"><option value="classic" ${cfg.themePreset==='classic'?'selected':''}>Classic</option><option value="vibrant" ${cfg.themePreset==='vibrant'?'selected':''}>Vibrant</option><option value="soft" ${cfg.themePreset==='soft'?'selected':''}>Soft</option></select></div><div class="field"><label>Heading Size</label><input id="setHeadingSize" type="number" min="20" max="56" value="${Number(cfg.headingSize)||32}"></div><div class="field"><label>Background</label><input id="setBg" type="color" value="${cfg.backgroundColor||'#f7f8ff'}"></div><div class="field"><label>Text Color</label><input id="setText" type="color" value="${cfg.textColor||'#111827'}"></div><div class="field"><label>Main/Profile Color</label><input id="setAccent" type="color" value="${cfg.accentColor||'#7c3aed'}"></div><div class="field"><label>Button Color</label><input id="setButton" type="color" value="${cfg.buttonColor||'#7c3aed'}"></div></div><div class="field"><label>Company Logo</label><input id="setLogo" type="file" accept="image/*">${cfg.logo?`<img src="${cfg.logo}" style="width:90px;height:70px;object-fit:contain;border:1px solid #ddd;border-radius:12px;margin-top:8px">`:''}</div><button class="btn green" style="width:100%;padding:14px" onclick="saveBranding()">💾 Save Branding Online</button>`;return}
if(part==='payment'){$('ownerBody').innerHTML=ownerSettingsNav(part)+`<h3>💳 Payment / Delivery</h3><div class="checkoutGrid"><div class="field"><label>Delivery Amount</label><input id="setDelivery" type="number" min="0" value="${Number(cfg.deliveryFee)||0}"></div><div class="field"><label>My UPI ID</label><input id="setUPI" value="${esc(cfg.upiId||'')}" oninput="previewUPIQR()" placeholder="example@upi"></div><div class="field"><label>Owner WhatsApp Number</label><input id="setWA" value="${esc(cfg.whatsappNumber||'')}" inputmode="numeric"></div><div class="field"><label>Global Discount %</label><input id="setDiscount" type="number" min="0" max="100" value="${Number(cfg.discountPercent)||0}"></div></div><label class="field"><span><input id="setSale" type="checkbox" ${cfg.saleEnabled?'checked':''}> Show SALE badge</span></label><div class="field"><label>Payment QR</label><div style="display:flex;gap:12px;align-items:flex-start;flex-wrap:wrap"><div><input id="setQR" type="file" accept="image/*" onchange="previewUPIQR()"><div class="mini">Upload your own QR, or leave empty and QR will be generated from My UPI ID.</div></div><div><img id="ownerQRPreview" src="${cfg.qrCode||''}" class="qr ${cfg.qrCode?'':'hidden'}" style="max-width:180px"></div></div></div><button class="btn green" style="width:100%;padding:14px" onclick="savePayment()">💾 Save Payment & Delivery Permanently</button>`;previewUPIQR();return}
if(part==='offer'){let posters=Array.isArray(cfg.posters)?cfg.posters:[],ph='';for(let i=0;i<6;i++){const x=posters[i]||{};ph+=`<div class="posterEditor"><h4>🖼️ Poster ${i+1}</h4><div class="checkoutGrid"><div class="field"><label>Title</label><input id="posterTitle${i}" value="${esc(x.title||'')}" placeholder="FREE DELIVERY"></div><div class="field"><label>Text / Notification</label><textarea id="posterText${i}" rows="2" placeholder="Any customer buying 5+ gets discount">${esc(x.text||'')}</textarea></div><div class="field"><label>Background</label><input id="posterBg${i}" type="color" value="${x.bgColor||'#7c3aed'}"></div><div class="field"><label>Text Colour</label><input id="posterTextColor${i}" type="color" value="${x.textColor||'#ffffff'}"></div><div class="field"><label>Text Size</label><input id="posterSize${i}" type="number" min="14" max="48" value="${Number(x.fontSize)||24}"></div><div class="field"><label>Style</label><select id="posterStyle${i}"><option value="bold" ${x.fontStyle==='bold'||!x.fontStyle?'selected':''}>Bold</option><option value="normal" ${x.fontStyle==='normal'?'selected':''}>Normal</option><option value="italic" ${x.fontStyle==='italic'?'selected':''}>Italic</option></select></div><div class="field"><label>Alignment</label><select id="posterAlign${i}"><option value="left" ${x.align==='left'?'selected':''}>Left</option><option value="center" ${x.align==='center'||!x.align?'selected':''}>Center</option><option value="right" ${x.align==='right'?'selected':''}>Right</option></select></div><div class="field"><label>Poster Image (optional)</label><input id="posterImage${i}" type="file" accept="image/*"></div></div>${x.image?`<input id="posterExisting${i}" type="hidden" value="${esc(x.image)}"><img src="${x.image}" style="width:100%;max-height:130px;object-fit:cover;border-radius:12px;margin-top:8px">`:''}</div>`}let couponRows='';try{const rr=await fetch('/api/admin/coupons',{cache:'no-store'}),dd=await rr.json();couponRows=(dd.coupons||[]).map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>${c.discount_type==='fixed'?'₹'+Number(c.discount_value).toFixed(2):Number(c.discount_value)+'%'}</td><td>${Number(c.min_qty)}+</td><td>${Number(c.min_amount||0)>0?'₹'+Number(c.min_amount).toFixed(0):'—'}</td><td>${Number(c.used_count||0)}/${Number(c.max_uses||0)||'∞'}</td><td>${c.active?'Active':'Off'}</td><td><button class="btn light" onclick="toggleCoupon(${c.id},${c.active?0:1})">${c.active?'Disable':'Enable'}</button> <button class="btn red" onclick="deleteCoupon(${c.id})">Delete</button></td></tr>`).join('')}catch{}$('ownerBody').innerHTML=ownerSettingsNav(part)+`<h3>🎉 Offers / Notifications / Posters</h3><label class="field"><span><input id="setOfferEnabled" type="checkbox" ${cfg.offerEnabled!==false?'checked':''}> Offer enabled</span></label><div class="field"><label>Main Offer Headline</label><input id="setOfferHeadline" value="${esc(cfg.offerHeadline||'Special PVC Card Offer')}"></div><div class="field"><label>Main Notification Text</label><textarea id="setOfferSubtext" rows="3">${esc(cfg.offerSubtext||'Limited-time discount available')}</textarea></div><div class="checkoutGrid"><div class="field"><label>Start</label><input id="setOfferStart" type="datetime-local" value="${esc(cfg.offerStart||'')}"></div><div class="field"><label>End</label><input id="setOfferEnd" type="datetime-local" value="${esc(cfg.offerEnd||'')}"></div></div><div class="field"><label>Legacy Main Poster (optional)</label><input id="setOfferPoster" type="file" accept="image/*">${cfg.offerPoster?`<img src="${cfg.offerPoster}" style="width:100%;max-height:140px;object-fit:cover;border-radius:14px;margin-top:8px">`:''}</div><button class="btn green" style="width:100%;padding:14px" onclick="saveOffer()">💾 Save Main Offer</button><h3 style="margin-top:24px">🖼️ Add Your Own Poster Boxes</h3><div class="mini">Create up to 6 posters such as FREE DELIVERY, 5+ quantity discount, festival offers, notices, etc. Choose your own text, colour, size and style.</div>${ph}<button class="btn green" style="width:100%;padding:14px" onclick="savePosters()">💾 Save All Poster Boxes</button><h3 style="margin-top:24px">🎟️ Coupon System</h3><div class="checkoutGrid"><div class="field"><label>Coupon Code</label><input id="couponCode" placeholder="SAVE5"></div><div class="field"><label>Discount Type</label><select id="couponType"><option value="percent">Percentage %</option><option value="fixed">Fixed ₹</option></select></div><div class="field"><label>Discount Value</label><input id="couponValue" type="number" min="0"></div><div class="field"><label>Minimum Quantity</label><input id="couponMinQty" type="number" min="1" value="5"></div><div class="field"><label>Minimum Purchase ₹</label><input id="couponMinAmount" type="number" min="0" value="0"></div><div class="field"><label>Maximum Uses (0 = unlimited)</label><input id="couponMaxUses" type="number" min="0" value="0"></div></div><button class="btn primary" style="width:100%;padding:14px" onclick="saveCoupon()">🎟️ Save Coupon</button><div class="tablewrap" style="margin-top:12px"><table class="table"><thead><tr><th>Code</th><th>Discount</th><th>Min Qty</th><th>Min Amount</th><th>Uses</th><th>Status</th><th>Action</th></tr></thead><tbody>${couponRows||'<tr><td colspan="7">No coupons yet.</td></tr>'}</tbody></table></div>`;return}
if(part==='quantity'){await loadProducts();const rows=PRODUCTS.map(p=>{const q=offersFor(p);return `<tr><td><b>${esc(p.title)}</b></td>${[0,1,2,3,4].map(j=>`<td><input id="qp_${p.id}_${j}" type="number" min="0" value="${Number(q[j]?.price??p.price??0)}" style="width:90px;padding:8px;border:1px solid #cbd5e1;border-radius:8px"></td>`).join('')}</tr>`}).join('');$('ownerBody').innerHTML=ownerSettingsNav(part)+`<h3>📊 Quantity-wise Offers</h3><div class="tablewrap"><table class="table"><thead><tr><th>Product</th><th>1+</th><th>5+</th><th>10+</th><th>25+</th><th>50+</th></tr></thead><tbody>${rows}</tbody></table></div><button class="btn green" style="width:100%;padding:14px;margin-top:14px" onclick="saveQuantityOffers()">💾 Save Quantity Offers Online</button>`;return}}
async function saveBranding(){try{const logo=await imageData('setLogo');const payload={brandName:val('setBrandName').trim(),tagline:val('setTagline').trim(),supportPhone:val('setSupportPhone').replace(/\D/g,'').slice(-10),supportEmail:val('setSupportEmail').trim(),themePreset:val('setTheme','vibrant'),headingSize:Number(val('setHeadingSize',32))||32,backgroundColor:val('setBg','#f7f8ff'),textColor:val('setText','#111827'),accentColor:val('setAccent','#7c3aed'),buttonColor:val('setButton','#7c3aed')};if(logo)payload.logo=logo;const r=await fetch('/api/admin/branding',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Branding save failed.');cfg={...cfg,...(d.config||{})};applyBranding();toast('Branding saved permanently.')}catch(e){toast('❌ '+(e?.message||e||'Branding save failed.'))}}
function upiPaymentLinks(upi,amount){upi=String(upi||'').trim();amount=Number(amount||0).toFixed(2);if(!upi)return {};const q='pa='+encodeURIComponent(upi)+'&pn='+encodeURIComponent(cfg.brandName||'B2B PVC PRINTING SHOP')+'&am='+encodeURIComponent(amount)+'&cu=INR';return {upi:'upi://pay?'+q,phonepe:'intent://pay?'+q+'#Intent;scheme=upi;package=com.phonepe.app;end',gpay:'intent://pay?'+q+'#Intent;scheme=upi;package=com.google.android.apps.nbu.paisa.user;end',paytm:'intent://pay?'+q+'#Intent;scheme=upi;package=net.one97.paytm;end'};}
function upiQRUrl(upi){upi=String(upi||'').trim();if(!upi)return '';const data='upi://pay?pa='+encodeURIComponent(upi)+'&pn='+encodeURIComponent(cfg.brandName||'B2B PVC PRINTING SHOP')+'&cu=INR';return 'https://api.qrserver.com/v1/create-qr-code/?size=320x320&margin=8&data='+encodeURIComponent(data)}
function previewUPIQR(){const el=$('ownerQRPreview');if(!el)return;const upi=$('setUPI')?.value.trim()||'';const custom=$('setQR')?.files?.length;const url=custom?'':(upiQRUrl(upi)||cfg.qrCode||'');el.src=url;el.classList.toggle('hidden',!url)}
async function savePayment(){try{const qr=await imageData('setQR'),upi=val('setUPI').trim(),payload={deliveryFee:Number(val('setDelivery',0))||0,upiId:upi,qrCodeUrl:qr?'':upiQRUrl(upi),whatsappNumber:val('setWA').replace(/\D/g,'').slice(-10),discountPercent:Number(val('setDiscount',0))||0,discountEnabled:true,saleEnabled:checked('setSale')};if(qr)payload.qrCode=qr;const r=await fetch('/api/admin/payment',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw new Error(d.error||'Payment save failed.');cfg={...cfg,...d.config};renderCheckout();toast('Payment & delivery saved permanently. QR is ready for customer payment.')}catch(e){toast('❌ '+e.message)}}
async function savePosters(){try{const posts=[];for(let i=0;i<6;i++){const title=val('posterTitle'+i).trim(),text=val('posterText'+i).trim(),img=await imageData('posterImage'+i);if(!title&&!text&&!img)continue;posts.push({title,text,bgColor:val('posterBg'+i,'#7c3aed'),textColor:val('posterTextColor'+i,'#ffffff'),fontSize:Number(val('posterSize'+i,24))||24,fontStyle:val('posterStyle'+i,'bold'),align:val('posterAlign'+i,'center'),imageData:img,image:val('posterExisting'+i,'')})}const r=await fetch('/api/admin/posters',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({posters:posts})}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Poster save failed.');cfg={...cfg,...(d.config||{})};renderOffer();toast('Posters and notifications saved permanently.')}catch(e){toast('❌ '+(e?.message||e))}}
async function saveCoupon(){try{const payload={code:val('couponCode').trim(),discountType:val('couponType','percent'),discountValue:Number(val('couponValue',0))||0,minQty:Number(val('couponMinQty',1))||1,minAmount:Number(val('couponMinAmount',0))||0,maxUses:Number(val('couponMaxUses',0))||0};const r=await fetch('/api/admin/coupons',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Coupon save failed.');toast('Coupon saved.');ownerSettingsPart('offer')}catch(e){toast('❌ '+(e?.message||e))}}
async function toggleCoupon(id,active){try{const r=await fetch('/api/admin/coupons/'+id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({active})});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||'Coupon update failed.')}ownerSettingsPart('offer')}catch(e){toast('❌ '+e.message)}}
async function deleteCoupon(id){if(!confirm('Delete this coupon?'))return;try{const r=await fetch('/api/admin/coupons/'+id,{method:'DELETE'});if(!r.ok)throw new Error('Coupon delete failed.');ownerSettingsPart('offer')}catch(e){toast('❌ '+e.message)}}
async function applyCoupon(){const code=val('checkoutCoupon').trim().toUpperCase();if(!code){appliedCoupon=null;return renderCheckout()}try{const t=totals(),quantity=getCart().reduce((a,x)=>a+Number(x.qty||1),0),r=await fetch('/api/coupon-check',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code,subtotal:t.subtotal,quantity})}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Coupon not valid.');appliedCoupon=d;renderCheckout();toast(`Coupon applied: ₹${Number(d.discount||0).toFixed(2)} off`)}catch(e){appliedCoupon=null;toast('❌ '+e.message)}}
async function saveOffer(){try{const poster=await imageData('setOfferPoster');const payload={offerEnabled:$('setOfferEnabled').checked,offerHeadline:$('setOfferHeadline').value.trim(),offerSubtext:$('setOfferSubtext').value.trim(),offerStart:$('setOfferStart').value,offerEnd:$('setOfferEnd').value};if(poster)payload.offerPoster=poster;const r=await fetch('/api/admin/offer',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw new Error(d.error||'Offer save failed.');cfg={...cfg,...d.config};renderOffer();toast('Offer saved permanently.')}catch(e){toast('❌ '+e.message)}}
async function saveQuantityOffers(){try{const q={};for(const p of PRODUCTS)q[p.id]=[1,5,10,25,50].map((m,j)=>({min:m,price:Number($('qp_'+p.id+'_'+j).value)||0}));const r=await fetch('/api/admin/quantity-offers',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({quantityOffers:q})}),d=await r.json();if(!r.ok)throw new Error(d.error||'Quantity save failed.');await loadProducts();toast('Quantity offers saved permanently.')}catch(e){toast('❌ '+e.message)}}
async function ownerProducts(){if(!owner)return openOwnerLogin();$('ownerBody').innerHTML='<div style="padding:25px;text-align:center">⏳ Loading products...</div>';try{const r=await fetch('/api/products',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load products.');PRODUCTS=d.products||[];const cards=PRODUCTS.map(p=>`<div class="historyCard"><div style="display:flex;gap:12px;align-items:center"><img src="${p.images?.[0]||''}" loading="lazy" style="width:70px;height:55px;object-fit:contain;border-radius:8px;background:#f8fafc"><div style="flex:1"><b>${esc(p.title)}</b><div class="mini">MRP ₹${Number(p.mrp||0)} • Price ₹${Number(p.price||0)} • ${esc(p.offerBadge||'No badge')}</div></div><button class="btn primary" onclick="editProduct('${encodeURIComponent(p.id)}')">Edit</button><button class="btn red" onclick="deleteProduct('${encodeURIComponent(p.id)}')">Hide</button></div></div>`).join('');$('ownerBody').innerHTML=`<div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><h3>🛍️ Product Manager (${PRODUCTS.length})</h3><button class="btn green" onclick="editProduct('')">➕ Add New Product</button></div><div class="mini" style="margin-bottom:12px">You can add unlimited products and edit MRP, selling price, discount/offer badge, description, quantity pricing and image.</div>${cards||'<div class="mini">No products.</div>'}`}catch(e){$('ownerBody').innerHTML='<div style="color:#b91c1c;font-weight:800">❌ '+esc(e.message)+'</div>'}}
function editProduct(id){const p=id?PRODUCTS.find(x=>x.id===decodeURIComponent(id)):null;const q=offersFor(p||{price:0});$('ownerBody').innerHTML=`<h3>${p?'✏️ Edit Product':'➕ Add Product'}</h3><div class="checkoutGrid"><div class="field"><label>Product Name *</label><input id="prTitle" value="${esc(p?.title||'')}"></div><div class="field"><label>Product ID</label><input id="prId" value="${esc(p?.id||'')}" placeholder="auto if blank" ${p?'disabled':''}></div><div class="field"><label>Category / Tag</label><input id="prTag" value="${esc(p?.tag||'PVC Card')}"></div><div class="field"><label>MRP</label><input id="prMrp" type="number" min="0" value="${Number(p?.mrp||0)}"></div><div class="field"><label>Selling Price</label><input id="prPrice" type="number" min="0" value="${Number(p?.price||0)}"></div><div class="field"><label>Offer / Discount Badge</label><input id="prBadge" value="${esc(p?.offerBadge||'')}" placeholder="20% OFF / SALE"></div><div class="field"><label>Discount %</label><input id="prDiscount" type="number" min="0" max="100" value="${Number(p?.discountPercent||0)}"></div></div><div class="field"><label>Description</label><textarea id="prDesc" rows="4">${esc(p?.desc||'')}</textarea></div><div class="field"><label>Product Images (up to 3)</label><input id="prImages" type="file" accept="image/*" multiple onchange="previewProductImages()"><div class="mini">Upload 1–3 images. New uploads permanently replace the old product gallery.</div><div id="prImagePreview" style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px">${(p?.images||[]).slice(0,3).map(u=>`<img src="${u}" loading="lazy" style="width:120px;height:90px;object-fit:contain;border:1px solid #ddd;border-radius:10px;background:#f8fafc">`).join('')}</div></div><h4>Quantity Pricing</h4><div class="checkoutGrid">${[1,5,10,25,50].map((m,j)=>`<div class="field"><label>${m}+ Quantity Price</label><input id="prQ${m}" type="number" min="0" value="${Number(q[j]?.price??p?.price??0)}"></div>`).join('')}</div><button class="btn green" style="width:100%;padding:14px" onclick="saveProduct('${encodeURIComponent(p?.id||'')}')">💾 Save Product</button><button class="btn light" style="width:100%;padding:12px;margin-top:8px" onclick="ownerProducts()">← Back to Products</button>`}
async function deleteProduct(id){if(!confirm('Hide this product from customers?'))return;try{const r=await fetch('/api/admin/products/'+id,{method:'DELETE'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not hide product.');toast('Product hidden.');await loadProducts();ownerProducts()}catch(e){toast(e.message)}}
function previewProductImages(){const box=$('prImagePreview');if(!box)return;const files=Array.from($('prImages')?.files||[]).slice(0,3);if(!files.length)return;box.innerHTML='';files.forEach(f=>{const u=URL.createObjectURL(f);const im=document.createElement('img');im.src=u;im.style='width:120px;height:90px;object-fit:contain;border:1px solid #ddd;border-radius:10px;background:#f8fafc';box.appendChild(im);im.onload=()=>URL.revokeObjectURL(u)})}
async function saveProduct(id){try{const images=await imageDataMulti('prImages'),payload={title:$('prTitle').value.trim(),id:$('prId').value.trim(),tag:$('prTag').value.trim(),mrp:Number($('prMrp').value)||0,price:Number($('prPrice').value)||0,offerBadge:$('prBadge').value.trim(),description:$('prDesc').value.trim(),discountPercent:Number($('prDiscount').value)||0,quantityOffers:[1,5,10,25,50].map(m=>({min:m,price:Number($('prQ'+m).value)||0}))};if(images.length)payload.imageDataList=images;const url=id?'/api/admin/products/'+id:'/api/admin/products',r=await fetch(url,{method:id?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw new Error(d.error||'Product save failed.');toast('Product saved permanently.');await loadProducts();ownerProducts()}catch(e){toast('❌ '+e.message)}}
async function ownerSupport(){if(!owner)return openOwnerLogin();$('ownerBody').innerHTML='<div style=\"padding:25px;text-align:center\">⏳ Loading customer feedback...</div>';try{const r=await fetch('/api/admin/support',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load messages.');const rows=(d.messages||[]).map(m=>`<tr><td><b>${esc(m.type)}</b><br>${esc(m.subject||'')}</td><td>${esc(m.customer_name)}<br>${esc(m.phone)}${m.email?'<br>'+esc(m.email):''}</td><td>${esc(m.order_no||'—')}</td><td style=\"white-space:pre-wrap\">${esc(m.message)}</td><td>${esc(m.status)}<br><small>${new Date(m.created_at).toLocaleString()}</small></td></tr>`).join('');$('ownerBody').innerHTML=`<h3>💬 Customer Feedback / Service / Complaint</h3><div class=\"tablewrap\"><table class=\"table\"><thead><tr><th>Type</th><th>Customer</th><th>Order</th><th>Message</th><th>Status / Date</th></tr></thead><tbody>${rows||'<tr><td colspan=\"5\">No messages yet.</td></tr>'}</tbody></table></div>`}catch(e){$('ownerBody').innerHTML='<div style=\"color:#b91c1c;font-weight:800\">❌ '+esc(e.message)+'</div>'}}
